BK='deliverables/backups/inline-images-before-2026-10-02'; os.makedirs(BK,exist_ok=True)
def fig(mid,alt):
    it=by[mid]; md=it.get('media_details',{}); sz=(md.get('sizes') or {}).get('large') or (md.get('sizes') or {}).get('medium_large')
    url=sz['source_url'] if sz else it['source_url']; w=sz['width'] if sz else md.get('width'); h=sz['height'] if sz else md.get('height')
    return f'<figure class="wp-block-image size-large"><img src="{url}" alt="{alt}" width="{w}" height="{h}" loading="lazy" decoding="async"><figcaption>{alt}</figcaption></figure>'
ids=[int(x) for x in sys.argv[1:]] or list(PLAN)
for pid in ids:
    d=json.loads(subprocess.run(['curl','-sS','-n','-m','90',f'https://arcadia-tour.com/wp-json/wp/v2/posts/{pid}?context=edit&_fields=id,content'],capture_output=True,text=True).stdout)
    c=d['content']['raw']; open(f'{BK}/{pid}.html','w',encoding='utf-8').write(c)
    if '<figure class="wp-block-image' in c: print(pid,'skip, has figure'); continue
    figs=[fig(mid,alt) for mid,alt in zip(PLAN[pid],ALT[pid])]
    i=c.find('</p>')+4; c=c[:i]+'\n'+figs[0]+c[i:]
    if len(figs)>1:
        h2s=[m.start() for m in re.finditer(r'<h2[\s>]',c)]
        pos=h2s[min(3,len(h2s)-2)]; c=c[:pos]+figs[1]+'\n'+c[pos:]
    json.dump({'content':c},open(f'expand/img_{pid}.json','w'),ensure_ascii=False)
    for a in range(3):
        r=subprocess.run(['curl','-sS','-n','-m','120',f'https://arcadia-tour.com/wp-json/wp/v2/posts/{pid}','-X','POST','-H','Content-Type: application/json','--data-binary',f'@expand/img_{pid}.json'],capture_output=True,text=True).stdout
        try: j=json.loads(r); print(pid,'imgs now',len(re.findall('<img',j['content']['raw']))); break
        except Exception: time.sleep(3)
    else: print(pid,'FAILED')
